// wywolane z Square: setWidth(5) ZMIENIA TEZ wysokosc na 5 -> area() = 25, NIE 20!

interface Shape { double area(); }
class Rectangle implements Shape {
    private double width, height;
    void setWidth(double w) { width = w; } // NIEZALEZNE od height
    public double area() { return width * height; }
}
class Square implements Shape {
    private double side;
    void setSide(double s) { side = s; } // WLASNY, spojny niezmiennik
    public double area() { return side * side; }
}

class Square extends Rectangle {
    @Override void setWidth(double w) { super.setWidth(w); super.setHeight(w); } // OSZUKUJE!
    @Override void setHeight(double h) { super.setWidth(h); super.setHeight(h); } // OSZUKUJE!
}
// kod napisany dla Rectangle.setWidth() zaklada, ze wysokosc NIE ulegnie zmianie

